package edu.campus.lostfound.web;
import edu.campus.lostfound.domain.*;import edu.campus.lostfound.repository.*;import edu.campus.lostfound.service.ReportService;import jakarta.validation.Valid;import java.util.List;import org.springframework.http.HttpStatus;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;
@RestController @RequestMapping("/api") public class ApiController{
 private final ReportService reports;private final ReportRepository reportRepository;private final MatchRepository matches;private final UserRepository users;private final NotificationRepository notifications;
 public ApiController(ReportService reports,ReportRepository reportRepository,MatchRepository matches,UserRepository users,NotificationRepository notifications){this.reports=reports;this.reportRepository=reportRepository;this.matches=matches;this.users=users;this.notifications=notifications;}
 @GetMapping("/health") Health health(){return new Health("UP","lost-item-intelligence-network");}
 @GetMapping("/reports")List<ReportView> list(@RequestParam(defaultValue="")String q,@RequestParam(required=false)ReportType type){return reports.search(q,type).stream().map(ReportView::from).toList();}
 @PostMapping("/reports")ReportView create(@Valid @RequestBody ReportService.CreateReport input,Authentication auth){return ReportView.from(reports.create(input,auth.getName()));}
 @GetMapping("/reports/{id}")ReportView detail(@PathVariable Long id){return ReportView.from(reportRepository.findById(id).orElseThrow());}
 @GetMapping("/matches/mine")@Transactional(readOnly=true)List<MatchView> mine(Authentication auth){Long user=users.findByEmailIgnoreCase(auth.getName()).orElseThrow().getId();return matches.findByLostReportOwnerIdOrFoundReportOwnerIdOrderByScoreDesc(user,user).stream().map(MatchView::from).toList();}
 @GetMapping("/notifications/mine")@Transactional(readOnly=true)List<NotificationView> notificationList(Authentication auth){Long user=users.findByEmailIgnoreCase(auth.getName()).orElseThrow().getId();return notifications.findTop30ByUserIdOrderByCreatedAtDesc(user).stream().map(NotificationView::from).toList();}
 @PostMapping("/notifications/{id}/read")@Transactional NotificationView markRead(@PathVariable Long id,Authentication auth){Long user=users.findByEmailIgnoreCase(auth.getName()).orElseThrow().getId();Notification notification=notifications.findByIdAndUserId(id,user).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));notification.markRead();return NotificationView.from(notification);}
 record Health(String status,String service){}
 record ReportView(Long id,ReportType type,String title,String category,String description,String location,java.time.LocalDate itemDate,java.time.LocalTime itemTime,ReportStatus status){static ReportView from(ItemReport r){return new ReportView(r.getId(),r.getType(),r.getTitle(),r.getCategory(),r.getDescription(),r.getLocation(),r.getItemDate(),r.getItemTime(),r.getStatus());}}
 record MatchView(Long id,Long lostReportId,Long foundReportId,double score,double categoryScore,double descriptionScore,double locationScore,double dateTimeScore,String explanation,String reviewStatus){static MatchView from(PotentialMatch m){return new MatchView(m.getId(),m.getLostReport().getId(),m.getFoundReport().getId(),m.getScore(),m.getCategoryScore(),m.getDescriptionScore(),m.getLocationScore(),m.getDateTimeScore(),m.getExplanation(),m.getReviewStatus());}}
 record NotificationView(Long id,String message,java.time.Instant createdAt,java.time.Instant readAt){static NotificationView from(Notification n){return new NotificationView(n.getId(),n.getMessage(),n.getCreatedAt(),n.getReadAt());}}
}
